__global__ void fused_allgather_gemm(input_chunk, weight, output) {
    // Phase 1: NVLink P2P load 从 peer GPU 读取远程 chunk 到 shared memory
    // Phase 2: 直接在 shared memory 上执行 GEMM Tensor Core MMA
